const fs = require('fs');
const DECISOES = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\auditoria\\decisoes.md';
const ALERTAS = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\auditoria\\alertas-automaticos.md';

function ultimaData(campo) {
  const todas = [...campo.matchAll(/(\d{4})-(\d{2})-(\d{2})/g)];
  if (todas.length === 0) return null;
  const u = todas[todas.length - 1];
  return new Date(Date.UTC(+u[1], +u[2]-1, +u[3]));
}

const content = fs.readFileSync(DECISOES, 'utf8');
const lines = content.split(/\r?\n/);
const hoje = new Date(); hoje.setUTCHours(0,0,0,0);

const vencidas = [];
for (const line of lines) {
  const t = line.trim();
  if (!t.startsWith('|')) continue;
  const cells = t.split('|').slice(1, -1).map(c => c.trim());
  if (cells.length !== 9) continue;
  const [data, categoria, nivel, oQueDecidi, , , revisarEm, resultadoReal] = cells;
  if (data === 'data' || data === '---') continue;
  if (!/pendente/i.test(resultadoReal)) continue;
  const d = ultimaData(revisarEm);
  if (!d) continue;
  if (d.getTime() < hoje.getTime()) {
    vencidas.push({
      data, categoria,
      resumo: oQueDecidi.replace(/\*\*/g, '').slice(0, 100),
      revisarEm,
      diasVencido: Math.round((hoje - d) / 86400000)
    });
  }
}
vencidas.sort((a, b) => b.diasVencido - a.diasVencido);

const agora = new Date();
const pad = n => String(n).padStart(2, '0');
const dataStr = `${agora.getUTCFullYear()}-${pad(agora.getUTCMonth()+1)}-${pad(agora.getUTCDate())}`;
const horaStr = `${pad(agora.getUTCHours())}:${pad(agora.getUTCMinutes())}`;

let bloco = `\n## ${dataStr} ${horaStr} — n8n (automático, Decisão com Revisão Vencida)\n\n`;
if (vencidas.length === 0) {
  bloco += 'Nenhuma decisão com revisão vencida e resultado ainda pendente.\n';
} else {
  bloco += `${vencidas.length} decisão(ões) com revisão vencida, resultado ainda pendente:\n\n`;
  for (const v of vencidas) {
    bloco += `- [${v.categoria}] decidido em ${v.data}, deveria revisar em ${v.revisarEm} (${v.diasVencido}d vencido): ${v.resumo}\n`;
  }
}

if (!fs.existsSync(ALERTAS)) {
  fs.writeFileSync(ALERTAS, '# Alertas automáticos — n8n\n\nLido pelo Diretor no início de toda sessão, junto com o resto de auditoria/.\n' + bloco, 'utf8');
} else {
  fs.appendFileSync(ALERTAS, bloco, 'utf8');
}

return [{ json: { vencidas: vencidas.length, detalhe: vencidas } }];
